with cleaned as (select id, product_name, category, brand, price, stock_qty, launch_date, tags, supplier_id, round(cost * 1.1, 2) cost_scaled from products where brand is not null) select id, brand, price, stock_qty, tags, lag(cost_scaled, 2) over w_recent prev_cost_scaled, avg(cost_scaled) over (partition by supplier_id order by price, id rows between 5 preceding and current row) cost_scaled_avg_5, ntile(3) over (partition by brand, supplier_id order by stock_qty, id) stock_qty_bucket from cleaned where brand is null window w_recent as (partition by category, supplier_id order by launch_date, id);
